const VALUE_PROPS = [
  {
    icon: Gem,
    title: "Эстетика и статус",
    text: "Видимый каркас GL24h, ручные соединения «шип-паз» — терраса как архитектурный объект",
  },
  {
    icon: ShieldCheck,
    title: "Надёжность на десятилетия",
    text: "Каждый узел — 2,5 тонны. Лиственница + Osmo UV-420. Гарантия 24 месяца, расчёт на 50+ лет",
  },
  {
    icon: PiggyBank,
    title: "Выгоднее металла за 10 лет",
    text: "TCO 1,39 млн ₽ vs 1,45 млн ₽ у стали. Ремонт без сварки, замена элементов поштучно",
  },
] as const;

export function CtaFinal() {
  return (
    <section className="bg-wood-800 py-16 md:py-24">
      <div className="max-w-[1440px] mx-auto px-4 md:px-8">
        <div className="flex flex-col items-center text-center gap-6 max-w-3xl mx-auto">
          <h2 className="font-heading text-3xl md:text-4xl font-bold text-wood-50">
            Готовы обсудить вашу террасу?
          </h2>
          <p className="text-wood-200 text-lg">
            Рассчитайте предварительную стоимость за 2 минуты — или позвоните,
            расскажем всё по телефону.
          </p>

          {/* Value propositions by persona */}
          <div className="grid sm:grid-cols-3 gap-4 w-full mt-2 mb-2">
            {VALUE_PROPS.map((prop) => (
              <div
                key={prop.title}
                className="rounded-lg border border-wood-600 bg-wood-700/50 p-4 text-left"
              >
                <prop.icon className="size-5 text-gold mb-2" />
                <p className="font-heading font-semibold text-wood-100 text-sm mb-1">
                  {prop.title}
                </p>
                <p className="text-wood-300 text-xs leading-relaxed">
                  {prop.text}
                </p>
              </div>
            ))}
          </div>

          <div className="flex flex-col sm:flex-row gap-4">
            <Button
              asChild
              className="bg-gold hover:bg-gold-light text-white text-lg px-8 py-3 h-auto focus-visible:ring-2 focus-visible:ring-gold focus-visible:outline-none"
            >
              <Link href="/kalkulyator">Рассчитать стоимость</Link>
            </Button>
            <Button
              asChild
              variant="outline"
              className="border-wood-200 text-wood-200 hover:bg-wood-700 text-lg px-8 py-3 h-auto focus-visible:ring-2 focus-visible:ring-gold focus-visible:outline-none"
            >
              <a href={`tel:${CONTACT.phoneRaw}`}>
                <Phone className="size-5" />
                Позвонить
              </a>
            </Button>
          </div>
        </div>
      </div>
    </section>
  );
}

