input.content:
// Calculator engine v2 — 7-step TF pricing with real market data
// Sources: Gemini market research (SPb 2025-2026), OpenCode architecture spec
// Calibrated: basic larch 200x200 M&T terrace ≈ 18,500 ₽/m²

// ============================================
// Types
// ============================================

export type ConstructionType = "terrace" | "veranda" | "canopy" | "pergola";
export type FoundationType = "screw_piles" | "concrete_pads" | "concrete_strip" | "existing";
export type BeamProfile = "150x150" | "200x200" | "200x240";
export type JointType = "mortise_tenon" | "dovetail" | "scarf";
export type FrameMaterial = "larch" | "oak" | "cedar";
export type RoofType = "none" | "polycarbonate" | "soft_tile" | "metal";
export type DeckingMaterial = "larch" | "thermowood" | "composite";
export type DeckingPattern = "straight" | "diagonal" | "herringbone";
export type FencingType = "none" | "wood_railing" | "glass_panel" | "combined";
export type CoatingBrand = "osmo" | "remmers" | "tikkurila";
export type ConfidenceLevel = "A" | "B" | "C";

export interface CalculationInputV2 {
  constructionType: ConstructionType;
  length: number;
  width: number;
  height: number;
  foundation: FoundationType;
  soilType: "sandy" | "clay" | "peat" | "rocky";
  beamProfile: BeamProfile;
  jointType: JointType;
  frameMaterial: FrameMaterial;
  roof: RoofType;
  decking: DeckingMaterial;
  deckingPattern: DeckingPattern;
  fencing: FencingType;
  coating: CoatingBrand;
  extras: {
    lighting: boolean;
    heating: boolean;
    socketCount: number;
    steps: boolean;
    gutter: boolean;
  };
}

export interface CostBreakdown {
  foundation: number;
  frame: number;
  decking: number;
  roof: number;
  fencing: number;
  coating: number;
  extras: number;
  labor: number;
}

export interface StopLine {
  message: string;
  action: "warn" | "block_pdf" | "require_contact";
}

export interface CalculationResult {
  min: number;
  max: number;
  breakdown: CostBreakdown;
  breakdownMax: CostBreakdown;
  pricePerM2: { min: number; max: number };
  totalArea: number;
  perimeter: number;
  confidenceLevel: ConfidenceLevel;
  confidenceReasons: string[];
  stopLines: StopLine[];
  tco: {
    tf10Year: number;
    standard10Year: number;
    metal10Year: number;
  };
  assumptions: string[];
}

// ============================================
// Pricing constants — calibrated from Gemini market research (SPb 2025-2026)
// ============================================

const PRICES = {
  // Foundation (installed, ₽)
  foundation: {
    screw_piles: { base: 3_500, perPile: 5_300 },
    concrete_pads: { base: 2_000, perPad: 4_250 },
    concrete_strip: { base: 2_500, perM2: 4_500 },
    existing: { inspection: 5_000 },
  },

  // Frame GL24h material (₽/m³)
  // Source: Gemini — GL24h 200x200 larch 110-135k, pine 65-75k
  frameMaterial: {
    larch: 122_000,
    oak: 170_000,
    cedar: 195_000,
  },

  // Frame volume factor (m³ of beam per m² of floor area)
  // Includes posts, beams, cross-members
  frameVolumeFactor: {
    "150x150": 0.040,
    "200x200": 0.065,
    "200x240": 0.080,
  } as Record<BeamProfile, number>,

  // Joint complexity multiplier (applied to frame cost)
  // M&T = baseline, dovetail +25% (more cuts), scarf +35% (precision)
  jointComplexity: {
    mortise_tenon: 1.0,
    dovetail: 1.25,
    scarf: 1.35,
  } as Record<JointType, number>,

  // Decking (₽/m², material only)
  // Source: Gemini — larch AB 1,450-1,850, thermoash 7,500-12,000, DPC 4,500-6,500
  decking: {
    larch: 1_650,
    thermowood: 7_500,
    composite: 5_200,
  } as Record<DeckingMaterial, number>,

  // Decking pattern waste/complexity multiplier
  deckingPattern: {
    straight: 1.0,
    diagonal: 1.12,
    herringbone: 1.30,
  } as Record<DeckingPattern, number>,

  // Roof (₽/m², material + install)
  // Source: Gemini — polycarbonate 4,500-6,000, soft tile 2,800-3,800
  roof: {
    none: 0,
    polycarbonate: 5_250,
    soft_tile: 3_300,
    metal: 4_200,
  } as Record<RoofType, number>,

  // Fencing (₽/linear meter, installed)
  // Source: Gemini — glass 22-32k, TF wood 8-12k, combined 18-25k
  fencing: {
    none: 0,
    wood_railing: 10_000,
    glass_panel: 27_000,
    combined: 21_500,
  } as Record<FencingType, number>,

  // Coating (₽/m², 2 coats applied)
  // Source: Gemini — Osmo 750-900, Remmers 600-750, Tikkurila 300-400
  coating: {
    osmo: 825,
    remmers: 675,
    tikkurila: 350,
  } as Record<CoatingBrand, number>,

  // Extras (₽, fixed prices)
  extras: {
    lighting: 15_000,
    heating: 45_000,
    socket: 3_500,
    steps: 18_000,
    gutter: 2_500, // per linear meter
  },

  // Labor rate (% of materials total)
  // Calibrated so basic 200x200 larch ≈ 18,500 ₽/m²
  laborRate: 0.60,

  // Uncertainty buffer for max price
  uncertaintyBuffer: 0.12,
} as const;

// Soil multiplier for pile count
const SOIL_PILE_MULTIPLIER: Record<string, number> = {
  sandy: 1.0,
  clay: 1.2,
  peat: 1.5,
  rocky: 0.8,
};

// ============================================
// Helpers
// ============================================

function roundTo1000(value: number): number {
  return Math.round(value / 1000) * 1000;
}

function estimatePileCount(area: number, soilType: string): number {
  const baseDensity = 4; // 1 pile per 4 m²
  const multiplier = SOIL_PILE_MULTIPLIER[soilType] ?? 1.0;
  return Math.ceil((area / baseDensity) * multiplier);
}

// ============================================
// Stop-lines evaluation
// ============================================

function evaluateStopLines(input: CalculationInputV2, area: number): StopLine[] {
  const lines: StopLine[] = [];

  if (input.height > 2.5 && input.roof === "none") {
    lines.push({
      message: "Высокая конструкция без кровли требует усиления для ветровой нагрузки",
      action: "warn",
    });
  }

  if (input.fencing === "glass_panel") {
    lines.push({
      message: "Стеклянное ограждение требует индивидуального расчёта и выезда на замер",
      action: "block_pdf",
    });
  }

  if (input.length > 8 || input.width > 6) {
    lines.push({
      message: "Крупноразмерная конструкция — требуется инженерный расчёт пролётов",
      action: "require_contact",
    });
  }

  if (input.soilType === "peat") {
    lines.push({
      message: "Торфяной грунт в ЛО — необходима геология и спецфундамент",
      action: "require_contact",
    });
  }

  if (area > 60) {
    lines.push({
      message: "Площадь более 60 м² — рекомендуем индивидуальный проект",
      action: "warn",
    });
  }

  return lines;
}

// ============================================
// Confidence determination
// ============================================

function determineConfidence(
  input: CalculationInputV2,
  stopLines: StopLine[]
): { level: ConfidenceLevel; reasons: string[] } {
  const reasons: string[] = [];

  const critical = stopLines.filter(
    (l) => l.action === "block_pdf" || l.action === "require_contact"
  );

  if (critical.length > 0) {
    return {
      level: "C",
      reasons: critical.map((l) => l.message),
    };
  }

  const warnings = stopLines.filter((l) => l.action === "warn");
  if (warnings.length > 0) {
    reasons.push(...warnings.map((l) => l.message));
  }

  if (input.beamProfile === "200x240" || input.jointType === "scarf") {
    reasons.push("Сложная конфигурация — уточнение после замера");
  }

  if (reasons.length > 0) {
    return { level: "B", reasons };
  }

  return { level: "A", reasons: [] };
}

// ============================================
// TCO calculation (10-year cost of ownership)
// Source: KB — TF 1.39M vs steel 1.45M for 30m²
// ============================================

function calculateTCO(area: number, tfInitialCost: number) {
  // Timber Frame: coating every 3 years
  const tfMaintenance = 3 * (area * 150); // 3 coatings in 10 years
  const tfTotal = tfInitialCost + tfMaintenance;

  // Standard pine terrace (metal brackets)
  const standardInitial = area * 12_000;
  const standardMaintenance =
    3 * (area * 200) + // coating every 2-3 years (more frequent)
    area * 3_500; // partial deck replacement at year 6
  const standardTotal = standardInitial + standardMaintenance;

  // Metal frame terrace
  const metalInitial = area * 18_000;
  const metalMaintenance =
    area * 800 + // repainting at year 5
    area * 2_500; // fastener replacement at year 8
  const metalTotal = metalInitial + metalMaintenance;

  return {
    tf10Year: roundTo1000(tfTotal),
    standard10Year: roundTo1000(standardTotal),
    metal10Year: roundTo1000(metalTotal),
  };
}

// ============================================
// Main calculation
// ============================================

export function calculatePriceV2(input: CalculationInputV2): CalculationResult {
  const area = Math.round(input.length * input.width * 10) / 10;
  const perimeter = 2 * (input.length + input.width);

  // 1. Foundation
  let foundationCost = 0;
  switch (input.foundation) {
    case "screw_piles": {
      const pileCount = estimatePileCount(area, input.soilType);
      foundationCost =
        PRICES.foundation.screw_piles.base +
        pileCount * PRICES.foundation.screw_piles.perPile;
      break;
    }
    case "concrete_pads": {
      const padCount = Math.ceil(area / 9);
      foundationCost =
        PRICES.foundation.concrete_pads.base +
        padCount * PRICES.foundation.concrete_pads.perPad;
      break;
    }
    case "concrete_strip":
      foundationCost =
        PRICES.foundation.concrete_strip.base +
        perimeter * PRICES.foundation.concrete_strip.perM2;
      break;
    case "existing":
      foundationCost = PRICES.foundation.existing.inspection;
      break;
  }

  // 2. Frame (GL24h)
  const frameVolume = area * PRICES.frameVolumeFactor[input.beamProfile];
  const frameMaterialCost = frameVolume * PRICES.frameMaterial[input.frameMaterial];
  const frameCost = frameMaterialCost * PRICES.jointComplexity[input.jointType];

  // 3. Decking
  const deckingBaseCost = area * PRICES.decking[input.decking];
  const deckingCost = deckingBaseCost * PRICES.deckingPattern[input.deckingPattern];

  // 4. Roof (with overhang factor 1.15)
  const roofArea = input.roof === "none" ? 0 : area * 1.15;
  const roofCost = roofArea * PRICES.roof[input.roof];

  // 5. Fencing
  const fencingCost = perimeter * PRICES.fencing[input.fencing];

  // 6. Coating
  const coatingCost = area * PRICES.coating[input.coating];

  // 7. Extras
  let extrasCost = 0;
  if (input.extras.lighting) extrasCost += PRICES.extras.lighting;
  if (input.extras.heating) extrasCost += PRICES.extras.heating;
  if (input.extras.steps) extrasCost += PRICES.extras.steps;
  if (input.extras.gutter) extrasCost += perimeter * PRICES.extras.gutter;
  extrasCost += input.extras.socketCount * PRICES.extras.socket;

  // 8. Labor
  const materialsTotal =
    foundationCost + frameCost + deckingCost + roofCost + fencingCost + coatingCost + extrasCost;
  const laborCost = materialsTotal * PRICES.laborRate;

  // Breakdown
  const breakdown: CostBreakdown = {
    foundation: roundTo1000(foundationCost),
    frame: roundTo1000(frameCost),
    decking: roundTo1000(deckingCost),
    roof: roundTo1000(roofCost),
    fencing: roundTo1000(fencingCost),
    coating: roundTo1000(coatingCost),
    extras: roundTo1000(extrasCost),
    labor: roundTo1000(laborCost),
  };

  const totalMin = Object.values(breakdown).reduce((a, b) => a + b, 0);
  const totalMax = roundTo1000(totalMin * (1 + PRICES.uncertaintyBuffer));

  const buf = 1 + PRICES.uncertaintyBuffer;
  const breakdownMax: CostBreakdown = {
    foundation: roundTo1000(breakdown.foundation * buf),
    frame: roundTo1000(breakdown.frame * buf),
    decking: roundTo1000(breakdown.decking * buf),
    roof: roundTo1000(breakdown.roof * buf),
    fencing: roundTo1000(breakdown.fencing * buf),
    coating: roundTo1000(breakdown.coating * buf),
    extras: breakdown.extras, // exact
    labor: roundTo1000(breakdown.labor * buf),
  };

  // Stop-lines and confidence
  const stopLines = evaluateStopLines(input, area);
  const { level: confidenceLevel, reasons: confidenceReasons } =
    determineConfidence(input, stopLines);

  // TCO
  const tco = calculateTCO(area, totalMin);

  // Assumptions
  const assumptions = [
