interface CalculatorActions {
  setStep: (step: number) => void;
  nextStep: () => void;
  prevStep: () => void;
  setConstructionType: (v: ConstructionType) => void;
  setLength: (v: number) => void;
  setWidth: (v: number) => void;
  setHeight: (v: number) => void;
  setFoundation: (v: FoundationType) => void;
  setSoilType: (v: CalculationInputV2["soilType"]) => void;
  setBeamProfile: (v: BeamProfile) => void;
