const initialState: CalculatorState = {
  // Step 1
  constructionType: "terrace",
  // Step 2
  length: 4,
  width: 3,
  height: 0.5,
  // Step 3
  foundation: "screw_piles",
  soilType: "sandy",
  // Step 4
  beamProfile: "200x200",
  jointType: "mortise_tenon",
  frameMaterial: "larch",
  // Step 5
  roof: "none",
  // Step 6
  decking: "larch",
  deckingPattern: "straight",
  fencing: "none",
  // Step 7
  coating: "osmo",
  extras: {
    lighting: false,
    heating: false,
    socketCount: 0,
    steps: false,
    gutter: false,
  },
  // Wizard
  currentStep: 1,
  completedSteps: new Set(),
  direction: "forward",
  result: null,
  aiText: "",
  aiLoading: false,
  aiError: false,
};

export const useCalculatorStore = create<CalculatorState & CalculatorActions>()(
  (set, get) => ({
    ...initialState,

    setStep: (step) => {
      const current = get().currentStep;
      set({
        currentStep: step,
        direction: step > current ? "forward" : "backward",
      });
    },

    nextStep: () => {
      const { currentStep, completedSteps } = get();
      if (currentStep < 7) {
        const next = new Set(completedSteps);
        next.add(currentStep);
        set({
          currentStep: currentStep + 1,
          completedSteps: next,
          direction: "forward",
        });
      }
    },

    prevStep: () => {
      const { currentStep } = get();
      if (currentStep > 1) {
        set({ currentStep: currentStep - 1, direction: "backward" });
      }
    },

    setConstructionType: (v) => set({ constructionType: v }),
    setLength: (v) => set({ length: v }),
    setWidth: (v) => set({ width: v }),
    setHeight: (v) => set({ height: v }),
    setFoundation: (v) => set({ foundation: v }),
    setSoilType: (v) => set({ soilType: v }),
    setBeamProfile: (v) => set({ beamProfile: v }),
    setJointType: (v) => set({ jointType: v }),
    setFrameMaterial: (v) => set({ frameMaterial: v }),
    setRoof: (v) => set({ roof: v }),
    setDecking: (v) => set({ decking: v }),
    setDeckingPattern: (v) => set({ deckingPattern: v }),
    setFencing: (v) => set({ fencing: v }),
    setCoating: (v) => set({ coating: v }),
    setExtra: (key, value) =>
      set((state) => ({
        extras: { ...state.extras, [key]: value },
      })),

    calculate: () => {
      const s = get();
      const input: CalculationInputV2 = {
        constructionType: s.constructionType,
        length: s.length,
        width: s.width,
        height: s.height,
        foundation: s.foundation,
        soilType: s.soilType,
        beamProfile: s.beamProfile,
        jointType: s.jointType,
        frameMaterial: s.frameMaterial,
        roof: s.roof,
        decking: s.decking,
        deckingPattern: s.deckingPattern,
        fencing: s.fencing,
        coating: s.coating,
        extras: s.extras,
      };
      const result = calculatePriceV2(input);
      const completed = new Set(s.completedSteps);
      completed.add(7);
      set({ result, completedSteps: completed });
    },

    reset: () => set({ ...initialState, completedSteps: new Set() }),

    setAiText: (aiText) => set({ aiText }),
    setAiLoading: (aiLoading) => set({ aiLoading }),
    setAiError: (aiError) => set({ aiError }),
  })
);

