function AIRecommendation() {
  const aiText = useCalculatorStore((s) => s.aiText);
  const aiLoading = useCalculatorStore((s) => s.aiLoading);
  const aiError = useCalculatorStore((s) => s.aiError);
  const setAiText = useCalculatorStore((s) => s.setAiText);
  const setAiLoading = useCalculatorStore((s) => s.setAiLoading);
  const setAiError = useCalculatorStore((s) => s.setAiError);

  const store = useCalculatorStore.getState();

  const handleRequest = useCallback(async () => {
    setAiLoading(true);
    setAiError(false);
    setAiText("");

    try {
      const response = await fetch("/api/ai/recommendation", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          area: store.length * store.width,
          material: store.frameMaterial,
          roof: store.roof,
          fencing: store.fencing,
          beamProfile: store.beamProfile,
          jointType: store.jointType,
          decking: store.decking,
          coating: store.coating,
        }),
      });

      if (!response.ok) throw new Error("API error");

      const reader = response.body?.getReader();
      if (!reader) throw new Error("No reader");

      const decoder = new TextDecoder();
      let accumulated = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        accumulated += decoder.decode(value, { stream: true });
        setAiText(accumulated);
      }
    } catch {
      setAiError(true);
    } finally {
      setAiLoading(false);
    }
  }, [store, setAiText, setAiLoading, setAiError]);

  if (aiText) {
    return (
      <div className="space-y-2">
        <h4 className="text-sm font-semibold text-gold-light flex items-center gap-2">
          <Sparkles className="w-4 h-4" />
          Рекомендация эксперта
        </h4>
        <p className="text-sm text-wood-200 leading-relaxed">{aiText}</p>
      </div>
    );
  }

  if (aiError) {
    return (
      <div className="space-y-2">
        <p className="text-sm text-wood-400">
          Не удалось получить рекомендацию
        </p>
        <Button
          size="sm"
          variant="outline"
          onClick={handleRequest}
          className="border-wood-500 text-wood-200 hover:bg-wood-700"
        >
          Попробовать снова
        </Button>
      </div>
    );
  }

  return (
    <Button
      size="sm"
      onClick={handleRequest}
      disabled={aiLoading}
      className="w-full bg-wood-700 hover:bg-wood-600 text-wood-100 border border-wood-500"
    >
      {aiLoading ? (
        <>
          <Loader2 className="w-4 h-4 animate-spin" />
          Анализируем конфигурацию...
        </>
      ) : (
        <>
          <Sparkles className="w-4 h-4" />
          Получить рекомендацию AI
        </>
      )}
    </Button>
  );
}

